{
  "verdict": "pended",
  "governing_rule": "MP-ONC-001",
  "reason": "Member eligibility, network status, benefit category, accumulator balance, and diagnosis support for rituximab (C83.30) are all satisfactory, and no conflicting authorization exists. However, the clinical justification submitted is generic template language (referencing physical therapy, anti-inflammatory medication, and imaging) and does not address the oncology-specific requirements of policy MP-ONC-001: the planned rituximab regimen, dose/schedule, and cycle number (Criterion 2), or documentation of baseline Hepatitis B surface antigen/core antibody screening prior to initiation (Criterion 3). Additional clinical information is needed before a determination can be made.",
  "missing_information": [
    "Documentation of the specific rituximab treatment regimen, planned dose, schedule, and cycle number consistent with an accepted protocol for diffuse large B-cell lymphoma",
    "Results of Hepatitis B surface antigen and core antibody screening performed prior to initiating rituximab"
  ]
}
